-- Aditiva. Ejecutar prechecks de duplicado de hash antes de producción.
CREATE TABLE `tbl_extracto_bancario` (`idextracto` INTEGER NOT NULL AUTO_INCREMENT, `idmandante` INTEGER NOT NULL, `institucionFinanciera` VARCHAR(120) NOT NULL, `cuenta` VARCHAR(80) NOT NULL, `moneda` VARCHAR(3) NOT NULL, `fechaDesde` DATETIME(3) NOT NULL, `fechaHasta` DATETIME(3) NOT NULL, `archivoNombre` VARCHAR(255) NOT NULL, `archivoHash` CHAR(64) NOT NULL, `creadoPor` INTEGER NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`idextracto`), UNIQUE INDEX `tbl_extracto_bancario_idmandante_archivoHash_key` (`idmandante`,`archivoHash`), INDEX `tbl_extracto_bancario_idmandante_fechaDesde_fechaHasta_idx` (`idmandante`,`fechaDesde`,`fechaHasta`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `tbl_extracto_linea` (`idlinea` INTEGER NOT NULL AUTO_INCREMENT, `idextracto` INTEGER NOT NULL, `fechaOperacion` DATETIME(3) NOT NULL, `fechaValor` DATETIME(3) NULL, `referenciaOriginal` VARCHAR(160) NULL, `referenciaNormalizada` VARCHAR(160) NULL, `descripcion` TEXT NULL, `debito` DECIMAL(14,2) NOT NULL DEFAULT 0, `credito` DECIMAL(14,2) NOT NULL DEFAULT 0, `monto` DECIMAL(14,2) NOT NULL, `moneda` VARCHAR(3) NOT NULL, `fingerprint` CHAR(64) NOT NULL, `estado` VARCHAR(24) NOT NULL DEFAULT 'PENDIENTE', PRIMARY KEY (`idlinea`), UNIQUE INDEX `tbl_extracto_linea_idextracto_fingerprint_key` (`idextracto`,`fingerprint`), INDEX `tbl_extracto_linea_estado_fechaOperacion_idx` (`estado`,`fechaOperacion`), INDEX `tbl_extracto_linea_referenciaNormalizada_idx` (`referenciaNormalizada`), CONSTRAINT `tbl_extracto_linea_idextracto_fkey` FOREIGN KEY (`idextracto`) REFERENCES `tbl_extracto_bancario`(`idextracto`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `tbl_conciliacion_pago` (`idconciliacion` INTEGER NOT NULL AUTO_INCREMENT, `idlinea` INTEGER NOT NULL, `idpago` INTEGER NOT NULL, `estado` VARCHAR(24) NOT NULL DEFAULT 'CONCILIADO', `metodoMatch` VARCHAR(32) NOT NULL, `confidence` DECIMAL(5,2) NOT NULL, `conciliadoPor` INTEGER NOT NULL, `conciliadoAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `motivoOverride` TEXT NULL, `desconciliadoPor` INTEGER NULL, `desconciliadoAt` DATETIME(3) NULL, `motivoDesconciliacion` TEXT NULL, PRIMARY KEY (`idconciliacion`), UNIQUE INDEX `tbl_conciliacion_pago_idlinea_idpago_key` (`idlinea`,`idpago`), INDEX `tbl_conciliacion_pago_idpago_estado_idx` (`idpago`,`estado`), CONSTRAINT `tbl_conciliacion_pago_idlinea_fkey` FOREIGN KEY (`idlinea`) REFERENCES `tbl_extracto_linea`(`idlinea`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `tbl_cierre_diario` (`idcierre` INTEGER NOT NULL AUTO_INCREMENT, `idmandante` INTEGER NOT NULL, `fechaNegocio` DATETIME(3) NOT NULL, `idagencia` INTEGER NULL, `idusuarioCaja` INTEGER NULL, `estado` VARCHAR(24) NOT NULL DEFAULT 'ABIERTO', `totalSistema` DECIMAL(14,2) NOT NULL DEFAULT 0, `totalDeclarado` DECIMAL(14,2) NOT NULL DEFAULT 0, `diferencia` DECIMAL(14,2) NOT NULL DEFAULT 0, `creadoPor` INTEGER NOT NULL, `revisadoPor` INTEGER NULL, `cerradoPor` INTEGER NULL, `motivoReapertura` TEXT NULL, `reopenedAt` DATETIME(3) NULL, `closedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`idcierre`), UNIQUE INDEX `tbl_cierre_diario_scope_key` (`idmandante`,`fechaNegocio`,`idagencia`,`idusuarioCaja`), INDEX `tbl_cierre_diario_idmandante_estado_fechaNegocio_idx` (`idmandante`,`estado`,`fechaNegocio`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `tbl_cierre_diario_detalle` (`iddetalle` INTEGER NOT NULL AUTO_INCREMENT, `idcierre` INTEGER NOT NULL, `medio` VARCHAR(32) NOT NULL, `montoSistema` DECIMAL(14,2) NOT NULL DEFAULT 0, `montoDeclarado` DECIMAL(14,2) NOT NULL DEFAULT 0, `diferencia` DECIMAL(14,2) NOT NULL DEFAULT 0, PRIMARY KEY (`iddetalle`), UNIQUE INDEX `tbl_cierre_diario_detalle_idcierre_medio_key` (`idcierre`,`medio`), CONSTRAINT `tbl_cierre_diario_detalle_idcierre_fkey` FOREIGN KEY (`idcierre`) REFERENCES `tbl_cierre_diario`(`idcierre`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
